SELECT

FROM UserInviteRewardConfig a WHERE 1 = 1

    AND a.currency = #{currency}


    AND a.tradeFeeSum1 = #{tradeFeeSum1}


    AND a.tradeFeeSum2 = #{tradeFeeSum2}


    AND a.rewardLevel = #{rewardLevel}


    AND a.rewardDiscount = #{rewardDiscount}


    AND a.state = #{state}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM UserInviteRewardConfig a WHERE 1 = 1

    AND a.currency LIKE CONCAT('%',#{currency}, '%')


    AND a.tradeFeeSum1 = #{tradeFeeSum1}


    AND a.tradeFeeSum2 = #{tradeFeeSum2}


    AND a.rewardLevel LIKE CONCAT('%',#{rewardLevel}, '%')


    AND a.rewardDiscount = #{rewardDiscount}


    AND a.state = #{state}


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}
